  voiceDenied: "\u9EA6\u514B\u98CE\u6388\u6743\u88AB\u62D2\u2014\u2014\u82E5\u5728 cenacle \u5185\u5D4C\u7A97\u53E3\u91CC\uFF0C\u8BF7\u6362\u72EC\u7ACB\u6807\u7B7E\u9875\u6253\u5F00 dsh \u518D\u5F00",
  voiceNoMic: "\u6CA1\u68C0\u6D4B\u5230\u9EA6\u514B\u98CE\u8BBE\u5907\uFF0C\u8BED\u97F3\u505C\u558A\u672A\u5F00\u542F",
  micDevice: "\u9EA6\u514B\u98CE\u8BBE\u5907",
